if (-NOT ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {exit}

$adapterKeyPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4D36E972-E325-11CE-BFC1-08002BE10318}"
$allAdapters = Get-ChildItem $adapterKeyPath -ErrorAction SilentlyContinue

$ethAdapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "Ethernet|LAN|GbE|Realtek|Intel|Killer|Broadcom|Qualcomm|BCM" }

foreach ($adapter in $ethAdapters) {
    $path = $adapter.PSPath

    # Remove all custom tweaks we added
    "EEE","*EEE","GreenEthernet","PowerSavingMode","AutoDisableGigabit","AdvancedEEE","EnableGreenEthernet","NicAutoPowerSaver","*WakeOnMagicPacket","*WakeOnPattern",
    "*InterruptModeration","InterruptModeration","RxIntModeration","TxIntModeration","*FlowControl","FlowControl",
    "*JumboPacket","JumboPacket","*RSS","*NumRssQueues","RSS",
    "*LsoV1IPv4","*LsoV2IPv4","*LsoV2IPv6","*RscIPv4","*RscIPv6",
    "*IPChecksumOffloadIPv4","*TCPChecksumOffloadIPv4","*UDPChecksumOffloadIPv4","*TCPChecksumOffloadIPv6","*UDPChecksumOffloadIPv6",
    "*ReceiveBuffers","*TransmitBuffers","RecvCompletionMethod","NdisPoll","ThreadPoll" | ForEach-Object {
        Remove-ItemProperty -Path $path -Name $_ -ErrorAction SilentlyContinue
    }
}

$wifiAdapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "Wi-Fi|Wireless|Realtek|Intel|Killer|Broadcom|Qualcomm|Atheros|BCM" }

foreach ($adapter in $wifiAdapters) {
    $path = $adapter.PSPath

    "PowerSavingMode","UAPSD","*UAPSD","*WakeOnMagicPacket","*WakeOnPattern","PacketCoalescing","*PacketCoalescing",
    "*TransmitPower","TransmitPower","RoamingAggressiveness","ThroughputBoosterEnabled","PreferredBand",
    "*PMARPOffload","*PMNSOffload" | ForEach-Object {
        Remove-ItemProperty -Path $path -Name $_ -ErrorAction SilentlyContinue
    }
}

# Intel I218/I219 specific fixes removal
try {
    $i219Adapters = $allAdapters | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DriverDesc -match "I218|I219" }
    foreach ($adapter in $i219Adapters) {
        $path = $adapter.PSPath
        "I219DisableK1Off","EnableD3ColdInS0","I218DisablePLLShut","I218DisablePLLShutGiga" | ForEach-Object {
            Remove-ItemProperty -Path $path -Name $_ -ErrorAction SilentlyContinue
        }
    }
} catch {}

